L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "양쪽 출입로가 파노라마의 영향을 받기 시작했으니, 아이린 양이 곧 증폭터널을 복제할 겁니다."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "両側の出入口がパノラマの影響を受け始めていますから、アイリーンさんがもうすぐ増幅トンネルを複製するはずです。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Now that both entrances are beginning to fall under Panorama's influence, Irene will soon duplicate the amplification tunnel."
L39_1.m_Talk_ENG = L40_1
