L41_1[L42_1] = true
L42_1 = "증폭터널이 정상적으로 작동하기 시작한 걸 보니, 녀석의 군세를 몰아내는데 성공한 모양이구나."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "増幅トンネルが正常に作動してるところを見るに、やつの軍勢を追い払うことに成功したようだね。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Since the amplification tunnel has started operating normally again, it looks like you succeeded in driving back their forces."
L41_1.m_Talk_ENG = L42_1
L42_1 = "既然增幅隧道開始正常運作，看來成功擊退那傢伙的軍勢了。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "Since the amplification tunnel has started operating normally again, it looks like you succeeded in driving back their forces."
