L42_1.m_Pos = "C"
L43_1 = "m_bCharHologramEffect"
L42_1[L43_1] = true
L43_1 = "지금부터 우린 예정대로 우물에 과부하를 걸어 초광역터널을 열 것이다. 그럼 제 역할을 다한 증폭터널은 곧 자연스럽게 닫히겠지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "今から私たちは予定どおりイドに過負荷をかけ、超広域トンネルを開く。そうなれば役割を果たした増幅トンネルはまもなく自然に閉まるはずだ。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "From here on, we'll proceed as planned and overload the Well to open a hyperwide tunnel. Once that happens, the amplification tunnel will naturally close after fulfilling its role."
L42_1.m_Talk_ENG = L43_1
L43_1 = "接下來我們會按照計畫讓井超載、開啟超廣域隧道。到時完成任務的增幅隧道就會自然關閉。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "From here on, we'll proceed as planned and overload the Well to open a hyperwide tunnel. Once that happens, the amplification tunnel will naturally close after fulfilling its role."
L42_1.m_Talk_DEU = L43_1
L43_1 = "From here on, we'll proceed as planned and overload the Well to open a hyperwide tunnel. Once that happens, the amplification tunnel will naturally close after fulfilling its role."
L42_1.m_Talk_FRA = L43_1
