L44_1 = "m_bCharHologramEffect"
L43_1[L44_1] = true
L44_1 = "그러니 너희는 현실로 부상할 준비를 해둬라. 뭐, 준비라고 해봐야 가만히 있으면 동앗줄이 알아서 다 해결해주겠지만?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "だからあなたたちは現実に浮上する準備をしておいて。まあ、準備といっても、じっとしてれば縄がすべて解決してくれるけど。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "So get ready to surface back into reality. Though honestly, there's nothing to prepare. The Straw Rope will take care of everything on its own."
L43_1.m_Talk_ENG = L44_1
L44_1 = "所以你們準備好浮出現實吧。不過說是準備，其實什麼都不用做，繩索自然會把你們拉上來。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "So get ready to surface back into reality. Though honestly, there's nothing to prepare. The Straw Rope will take care of everything on its own."
