L21_1.m_Face = "UNIT_LAUGH"
L21_1.m_CharStrID = "YEONHWA_ADMIN_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "제자에게 갖는 죄책감이 아니라도, 앞으로 많은 걸 짊어지고 나가실 분이잖아요?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "弟子に感じる罪悪感以外にも、これからたくさんのものを背負わないといけない方ですから。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Even without guilt toward your apprentice, you're someone who still has many things to carry forward."
L21_1.m_Talk_ENG = L22_1
L22_1 = "就算不是對弟子的愧疚，您也是未來要背負許多責任的人不是嗎？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "Even without guilt toward your apprentice, you're someone who still has many things to carry forward."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Even without guilt toward your apprentice, you're someone who still has many things to carry forward."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP15_ACT2_INTERLUDE11@121#Talk"
