L22_1.m_CharStrID = "YEONHWA_ADMIN_NULL_NULL"
L22_1.m_Pos = "C"
L23_1 = "전 말이죠. 제게 주어진 시간 동안 최선을 다해서 행복할 거에요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "私はね。自分に与えられた時間の中で、全力で幸せになります。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "As for me, I'm going to do my best to be happy for the time I've been given."
L22_1.m_Talk_ENG = L23_1
L23_1 = "我啊，在被賦予的時間內，會盡全力活得幸福。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "As for me, I'm going to do my best to be happy for the time I've been given."
L22_1.m_Talk_DEU = L23_1
L23_1 = "As for me, I'm going to do my best to be happy for the time I've been given."
L22_1.m_Talk_FRA = L23_1
