L39_1[L40_1] = true
L40_1 = "<color=#ffd34c>약 40초 후, 증폭터널이 폐쇄되며 체류 중인 인원은 진입한 출입로를 통해 배출됩니다.</color>"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "<color=#ffd34c>約40秒後、増幅トンネルが封鎖され、中に残っている人員は進入した出入口から排出されます。</color>"
L39_1.m_Talk_JPN = L40_1
L40_1 = "<color=#ffd34c>In approximately 40 seconds, the amplification tunnel will close, and all remaining personnel will be discharged through their entry points.</color>"
