L41_1.m_CharStrID = L42_1
L42_1 = "아주 많은 시련을 거쳤음에도... 그걸 모두 딛고 일어설 만큼 강인한 성정마저 닮았어."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "たくさんの試練を経験しても……それをすべて乗り越えられるほど強いところまでそっくりだ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Even after going through so many trials... he has the same strength of character to overcome all of them."
L41_1.m_Talk_ENG = L42_1
L42_1 = "即使經歷了那麼多試煉……仍然能重新站起來的堅強性格，也和你一樣。"
