L45_1.m_CharStrID = "YEONHWA_ADMIN_NULL_NULL"
L46_1 = "실은 제가 꿈꾸는 미래가... 남겨질 누군가의 삶을 원망으로 망가뜨리진 않을까, 많이 걱정했었거든요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "実は私が夢見ている未来が……残された誰かの人生を憎しみで台無しにしてしまうのではないかと、心配していたんです。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Actually, I was worried that the future I dream of... might end up ruining the life of someone left behind with resentment."
L45_1.m_Talk_ENG = L46_1
L46_1 = "其實我一直很擔心……我夢想的未來，會不會讓留下來的人因怨恨而毀掉人生。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "Actually, I was worried that the future I dream of... might end up ruining the life of someone left behind with resentment."
