L46_1.m_CharStrID = "YEONHWA_ADMIN_NULL_NULL"
L47_1 = "앞으로의 저는... 세상에서 제일 쓸 데 없는 걱정을 달고 살게 되겠네요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "これからの私は……世界で一番無駄な心配をすることになるでしょうね。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "From now on... I guess I'll be carrying around the most unnecessary worry in the world."
L46_1.m_Talk_ENG = L47_1
L47_1 = "看來以後的我……會帶著世界上最沒意義的擔心生活著。"
