L1_1.m_CharStrID = "YEONHWA_ADMIN_NULL_NULL"
L2_1 = "일부러 절 만나러 오지 않은 걸 텐데... 그래도 괜찮을까요?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "わざと私に会いに来なかったはずなのに……いいんでしょうか？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "He probably didn't come all this way to meet me on purpose... but would it still be all right?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "他明明不是特地來見我的……這樣真的沒關係嗎？"
L1_1.m_Talk_TWN = L2_1
