L3_1 = "HILDE_FENRIR_NEXT_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "저 녀석은 겁이 났을 뿐인 거다. 과거의 널 만나도 아는 척 할 수 없고. 행여나 낯선 취급을 받을까 봐 두려웠던 거지."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "あいつは怖かっただけだろう。過去のお前に会って声をかけることもできないし、もしかしたら余所余所しい態度を取られるかもしれないと思って。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "He was just scared. Even if he met the you from the past, he wouldn't be able to acknowledge you. He was afraid you might treat him like a stranger."
L2_1.m_Talk_ENG = L3_1
L3_1 = "那傢伙只是害怕而已。就算遇到過去的你也不能相認，怕被當成陌生人。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "He was just scared. Even if he met the you from the past, he wouldn't be able to acknowledge you. He was afraid you might treat him like a stranger."
L2_1.m_Talk_DEU = L3_1
L3_1 = "He was just scared. Even if he met the you from the past, he wouldn't be able to acknowledge you. He was afraid you might treat him like a stranger."
