L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "숱한 고비를 넘겨 마침내, 마왕과 대등하게 싸워볼 기회를 얻었군."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "幾多の苦難を乗り越え、ついに魔王と対等に戦う機会を手に入れたな。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "After overcoming so many trials, you've finally earned the chance to fight the Demon Lord on equal footing."
L33_1.m_Talk_ENG = L34_1
L34_1 = "歷經那麼多難關，終於得到能和魔王正面交手的機會。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "After overcoming so many trials, you've finally earned the chance to fight the Demon Lord on equal footing."
L33_1.m_Talk_DEU = L34_1
L34_1 = "After overcoming so many trials, you've finally earned the chance to fight the Demon Lord on equal footing."
L33_1.m_Talk_FRA = L34_1
