L34_1.m_Face = "UNIT_SERIOUS"
L34_1.m_CharStrID = "SPENCER_FLOOR_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "그래. 드디어 이 세계를 삼키려 드는 망할 나무뿌리의 근원을 부수러 가는 거야."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ああ。ついにこの世界を飲み込もうとしてる憎き木の根の根源を叩きに行くんだ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Yeah. At last, we're going to destroy the source of that damned tree root trying to swallow this world."
L34_1.m_Talk_ENG = L35_1
L35_1 = "沒錯。終於可以去摧毀那棵企圖吞噬這個世界的該死樹根源頭了。"
