L38_1 = "직통으로 길을 여는 건 위험하다고 판단했어. 미확인 에너지가 간섭하고 있거든. 아마도 마왕의 영향력이 직접적으로 닿는 곳이기 때문이겠지."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "直で道を開くのは危険と判断したんだ。未確認のエネルギーが干渉しているから。おそらく魔王の影響力が直接届いている場所だからだろう。"
