L5_1 = "전선을 사수하는 것도 중요하지만 누군가는 전쟁의 중심지로 가서 이 학살을 끝내야만 해."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "前線を死守することも大事だが、誰かは戦争の中心地に乗り込み、この虐殺を終わらせないといけない。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Holding the front lines is important too, but someone has to head to the heart of the war and put an end to this slaughter."
L4_1.m_Talk_ENG = L5_1
L5_1 = "固守前線固然重要，但總得有人前往戰爭的中心，結束這場屠殺。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "Holding the front lines is important too, but someone has to head to the heart of the war and put an end to this slaughter."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Holding the front lines is important too, but someone has to head to the heart of the war and put an end to this slaughter."
L4_1.m_Talk_FRA = L5_1
