L21_1 = "EP15_ACT2_INTERLUDE11@196#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 270
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 705
L20_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE11"
L20_1.m_bWaitClick = true
