L21_1 = "THEMA_COFFIN_FULL"
L20_1.m_StartBGMFileName = L21_1
L21_1 = "YOOMINA_FENRIR_NEXT_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "우물이... 가라앉고 있어. 마치 땅이 녹는 것처럼."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "イドが……沈んでいってる。まるで地面が溶けているみたいだ。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "The Well... It's sinking. It's like the ground is melting."
L20_1.m_Talk_ENG = L21_1
L21_1 = "井……在下沉，就像地面融化一樣。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "The Well... It's sinking. It's like the ground is melting."
L20_1.m_Talk_DEU = L21_1
L21_1 = "The Well... It's sinking. It's like the ground is melting."
L20_1.m_Talk_FRA = L21_1
