L22_1 = "EP15_ACT2_INTERLUDE11@197#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 271
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 705
L21_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE11"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_IDLE"
L21_1.m_CharStrID = "SPENCER_FLOOR_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "터널이 연결되면서 발생하는 공간 왜곡 현상이야. 눈에는 안 보이지만, 아마 시간축 역시 왜곡되고 있겠지."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "トンネルが繋がる時に発生する空間歪曲現象だ。目には見えないけど、たぶん時間軸も歪曲しているだろう。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "It's a spatial distortion phenomenon caused by the tunnel connecting. You can't see it, but the time axis is probably being distorted too."
L21_1.m_Talk_ENG = L22_1
L22_1 = "這是隧道連接時產生的空間扭曲現象。雖然肉眼看不見，但時間軸大概也被扭曲了。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "It's a spatial distortion phenomenon caused by the tunnel connecting. You can't see it, but the time axis is probably being distorted too."
L21_1.m_Talk_DEU = L22_1
L22_1 = "It's a spatial distortion phenomenon caused by the tunnel connecting. You can't see it, but the time axis is probably being distorted too."
L21_1.m_Talk_FRA = L22_1
