L23_1 = "EP15_ACT2_INTERLUDE11@198#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 272
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 705
L22_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE11"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
