L22_1.m_fTalkTime = 0.03
L23_1 = "大丈夫なの？　イドはタイムマシンの本体みたいなものなのに。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Is that okay? The Well was basically the core body of the time machine."
L22_1.m_Talk_ENG = L23_1
L23_1 = "沒問題嗎？那口井不是時光機的核心嗎？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "Is that okay? The Well was basically the core body of the time machine."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Is that okay? The Well was basically the core body of the time machine."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP15_ACT2_INTERLUDE11@199#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 273
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 705
L23_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE11"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_IDLE"
L23_1.m_CharStrID = "SPENCER_FLOOR_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "그 타임머신은 과거로 향하는 출입문을 열면서 제 역할을 다 했어. 다시 쓸 수는 없겠지."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "そのタイムマシンは過去へ向かう出入口を開けた時点でその役目を終えたんだ。もう使えないだろう。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "That time machine already fulfilled its role when it opened the gateway to the past. It won't be usable again."
L23_1.m_Talk_ENG = L24_1
L24_1 = "那台時光機在打開通往過去的入口時，就已經完成使命了，之後也無法再使用。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "That time machine already fulfilled its role when it opened the gateway to the past. It won't be usable again."
L23_1.m_Talk_DEU = L24_1
L24_1 = "That time machine already fulfilled its role when it opened the gateway to the past. It won't be usable again."
L23_1.m_Talk_FRA = L24_1
