L24_1.m_Talk_ENG = L25_1
L25_1 = "而且也不會再有機會用了。利用增幅隧道的機會本來就只有一次。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "We won't need to use it again anyway. We only had one chance to make use of the amplification tunnel to begin with."
L24_1.m_Talk_DEU = L25_1
L25_1 = "We won't need to use it again anyway. We only had one chance to make use of the amplification tunnel to begin with."
