L32_1 = "SEOSAENG_ATELIER_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "시간을 거리로 치환한 만큼, 걸어가는 것보단 차원함선을 이용하는 걸 권장하지."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "時間を距離に置換した分、歩くよりは次元艦船の利用をおすすめする。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Since time has been converted into distance, I recommend using dimensional ships rather than traveling on foot."
L31_1.m_Talk_ENG = L32_1
L32_1 = "既然把時間換算成距離了，我建議還是搭次元艦船比較好。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "Since time has been converted into distance, I recommend using dimensional ships rather than traveling on foot."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Since time has been converted into distance, I recommend using dimensional ships rather than traveling on foot."
L31_1.m_Talk_FRA = L32_1
