L33_1 = 282
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 705
L32_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE11"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
