L33_1 = "JIA_ALPHA_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "여과기 멜트다운까지 2.5초, 아슬아슬했네요."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ろ過機のメルトダウンまで2.5秒、ギリギリでしたね。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "2.5 seconds until filter meltdown. That was close."
